247	/// Options for step execution.
248	#[derive(Debug, Clone, Default)]
249	pub struct ExecutionOptions {
250	    /// Force run even if completed.
251	    pub force: bool,
252	
253	    /// Dry run mode (don't actually execute).
254	    pub dry_run: bool,
255	
256	    /// Capture output instead of streaming.
257	    pub capture_output: bool,
258	
259	    /// Additional secret patterns to mask.
260	    pub secret_patterns: Vec<String>,
261	}
