        process_env.insert("API_HOST".to_string(), "from_shell".to_string());

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions {
            capture_output: true,
            ..Default::default()
        };

        let result = execute_step(
            &step,
            temp.path(),
            &ctx,
            &base_env,
            &process_env,
            &options,
            None,
