    ) -> EngineContext<'a> {
        EngineContext {
            steps,
            project_root: Path::new("/tmp"),
            interpolation,
            snapshot_store,
            state: None,
            step_overrides: &EMPTY_OVERRIDES,
            force: &EMPTY_FORCE,
            force_all: false,
            named_check_results: &EMPTY_NAMED_CHECKS,
            satisfaction_cache,
            evaluated: HashMap::new(),
            failed_steps,
            user_skipped_steps,
