        assert_eq!(template.name, "brew-bundle");
        assert_eq!(source, TemplateSource::Builtin);
    }

    #[test]
    fn registry_fails_for_unknown() {
        let registry = Registry::new(None).unwrap();
        let result = registry.resolve("nonexistent");
