    #[test]
    fn different_entries_have_different_paths() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template1");
        let path2 = store.content_path("http:test", "template2");

        assert_ne!(path1, path2);
    }

    #[test]
    fn store_uses_atomic_write_no_temp_files_remain() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        let content_path = store.content_path("http:test", "template1");
        let meta_path = content_path.with_extension("meta.json");

        assert!(content_path.exists(), "content file should exist");
        assert!(meta_path.exists(), "metadata file should exist");

        let content_tmp = content_path.with_extension("tmp");
        let meta_tmp = meta_path.with_extension("tmp");
        assert!(
            !content_tmp.exists(),
            "content temp file should not remain after store"
        );
        assert!(
            !meta_tmp.exists(),
            "metadata temp file should not remain after store"
        );
    }

    #[test]
    fn update_uses_atomic_write_no_temp_files_remain() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store
            .store("http:test", "template1", "content", 3600)
            .unwrap();
        let updated = entry.with_etag("\"new-etag\"");
        store.update(&updated).unwrap();

        let content_path = store.content_path("http:test", "template1");
        let meta_path = content_path.with_extension("meta.json");
        let meta_tmp = meta_path.with_extension("tmp");

        assert!(meta_path.exists(), "metadata file should exist");
        assert!(
            !meta_tmp.exists(),
            "metadata temp file should not remain after update"
        );
    }

    #[test]
    fn concurrent_stores_produce_valid_metadata() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();
        let barrier = Arc::new(Barrier::new(4));

        let handles: Vec<_> = (0..4)
            .map(|i| {
                let root = root.clone();
                let barrier = Arc::clone(&barrier);
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    barrier.wait();
                    let content = format!("content from thread {}", i);
                    store
                        .store("http:test", "shared-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let store = CacheStore::new(&root);
        let entry = store
            .load("http:test", "shared-template")
            .unwrap()
            .expect("entry should exist after concurrent stores");

        let content = store.read_content(&entry).unwrap();
        assert!(
            content.starts_with("content from thread "),
            "content should be valid (not corrupted): {:?}",
            content
        );

        let loaded_json = std::fs::read_to_string(
            store
                .content_path("http:test", "shared-template")
                .with_extension("meta.json"),
        )
        .unwrap();
        let _: super::CacheEntry = serde_json::from_str(&loaded_json)
            .expect("metadata JSON should be valid (not corrupted)");
    }
}

