use super::entry::CacheEntry;

/// Write `data` to `path` atomically by writing to a sibling temp file first,
/// then renaming. On the same filesystem `rename` is atomic on POSIX, so
/// readers never see a partially-written file.
fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
    let tmp = path.with_extension("tmp");
    fs::write(&tmp, data)
        .with_context(|| format!("Failed to write temp file {:?}", tmp))?;
    fs::rename(&tmp, path)
        .with_context(|| format!("Failed to rename {:?} to {:?}", tmp, path))?;
    Ok(())
}

